void adl_serializer<tgbot::BotCommandScope>::to_json(json& j, const tgbot::BotCommandScope& value) {
    std::visit([&j](const auto& alt) { j = alt; }, value);
}
void adl_serializer<tgbot::BotCommandScope>::from_json(const json& j,
                                                       tgbot::BotCommandScope& value) {
    const auto& d = j.at("type").get_ref<const std::string&>();
    if (d == "all_chat_administrators") {
        value = j.get<tgbot::BotCommandScopeAllChatAdministrators>();
    } else if (d == "all_group_chats") {
        value = j.get<tgbot::BotCommandScopeAllGroupChats>();
    } else if (d == "all_private_chats") {
        value = j.get<tgbot::BotCommandScopeAllPrivateChats>();
    } else if (d == "chat") {
        value = j.get<tgbot::BotCommandScopeChat>();
    } else if (d == "chat_administrators") {
        value = j.get<tgbot::BotCommandScopeChatAdministrators>();
    } else if (d == "chat_member") {
        value = j.get<tgbot::BotCommandScopeChatMember>();
    } else if (d == "default") {
        value = j.get<tgbot::BotCommandScopeDefault>();
    } else {
        throw tgbot::Error("unknown BotCommandScope type: " + d);
    }
}

